#include <USBHIDKeyboard.h>

USBHIDKeyboard Keyboard;

const char* TARGET_PROCESS = "svhost.exe";

// Задержка между нажатиями (мс) — чтобы ОС успевала реагировать
const int KEY_DELAY = 20;
// Задержка после открытия диалога (мс)
const int DIALOG_DELAY = 600;

void typeString(const char* text) {
  for (int i = 0; text[i] != '\0'; i++) {
    Keyboard.write(text[i]);
    delay(KEY_DELAY);
  }
}

void setup() {
  Serial.begin(115200);
  Serial.println("ESP32-S3 BadUSB starting...");

  // Инициализация USB HID-клавиатуры
  Keyboard.begin();
  // Ждём, пока ОС опознает устройство как клавиатуру
  delay(2000);

  // 1. Открываем диалог «Выполнить» (Win + R)
  Keyboard.press(KEY_LEFT_GUI);  // клавиша Win
  Keyboard.press('r');
  delay(KEY_DELAY);
  Keyboard.releaseAll();
  delay(DIALOG_DELAY);

  // 2. Вводим команду для завершения процесса
  //    taskkill /F /IM svhost.exe
  String cmd = "taskkill /F /IM ";
  cmd += TARGET_PROCESS;

  typeString(cmd.c_str());
  delay(200);

  // 3. Нажимаем Enter
  Keyboard.press(KEY_RETURN);
  delay(KEY_DELAY);
  Keyboard.releaseAll();
  delay(1000);

  // 4. Закрываем окно (на случай ошибки — Esc)
  Keyboard.press(KEY_ESC);
  delay(KEY_DELAY);
  Keyboard.releaseAll();

  Serial.println("Done.");
  Keyboard.end();
}

void loop() {
  // Ничего не делаем — всё происходит один раз при подключении
}
